public TelemetryPipelineWiring(@Qualifier("validatedSamples") BoundedEventChannel<TelemetrySampleEvent> validatedSamples, @Qualifier("sequencedSamples") BoundedEventChannel<TelemetrySampleEvent> sequencedSamples, @Qualifier("backfillDetections") BoundedEventChannel<TelemetryBackfillDetectedEvent> backfillDetections, @Qualifier("closedWindows") BoundedEventChannel<TelemetryWindowClosedEvent> closedWindows, SequenceTelemetryUseCase sequence, RecordTelemetryUseCase record, BroadcastTelemetryUseCase broadcast) {
    this.validatedSamples = validatedSamples;
    this.sequencedSamples = sequencedSamples;
    this.backfillDetections = backfillDetections;
    this.closedWindows = closedWindows;
    this.sequence = sequence;
    this.record = record;
    this.broadcast = broadcast;
}

@Override
public synchronized void start() {
    if (running) {
        return;
    }
    subscriptions.add(subscribe(validatedSamples, sequence::onSampleReceived));
    subscriptions.add(subscribe(sequencedSamples, record::recordSequenced));
    subscriptions.add(subscribe(sequencedSamples, broadcast::broadcastSample));
    subscriptions.add(subscribe(backfillDetections, record::recordBackfill));
    subscriptions.add(subscribe(closedWindows, broadcast::broadcastWindow));
    running = true;
}

@Override
public synchronized void stop() {
    if (!running) {
        return;
    }
    subscriptions.forEach(Disposable::dispose);
    subscriptions.clear();
    running = false;
    sequence.flush().subscribe(ignored -> { }, error -> log.error("Sequencing flush failed", error));
}

private <E> Disposable subscribe(BoundedEventChannel<E> channel, Function<E, Mono<?>> handler) {
    return channel.stream()
            .concatMap(event -> Mono.defer(() -> handler.apply(event).then())
                    .onErrorResume(error -> {
                        log.error("Pipeline consumer failed on channel {}", channel.name(), error);
                        return Mono.empty();
                    }))
            .subscribe();
}
